//+------------------------------------------------------------------+
//| Reads the symbol universe from a plain-text file                 |
//+------------------------------------------------------------------+
bool
CSymbolRegistry::ReadUniverseFile(
string
&outSymbols[],
int
&outCount)
  {
   outCount =
0
;
int
handle =
FileOpen
(m_UniverseFilePath,
FILE_READ
|
FILE_TXT
|
FILE_ANSI
|
FILE_COMMON
);
if
(handle ==
INVALID_HANDLE
)
     {
Print
(
"SymbolRegistry: Cannot open universe file. Error: "
,
GetLastError
());
return
(
false
);
     }
ArrayResize
(outSymbols, MAX_SYMBOLS);
while
(!
FileIsEnding
(handle) && outCount < MAX_SYMBOLS)
     {
string
line =
FileReadString
(handle);
//--- Strip whitespace and skip empty lines or comments
StringTrimRight
(line);
StringTrimLeft
(line);
if
(
StringLen
(line) ==
0
)
continue
;
if
(
StringGetCharacter
(line,
0
) ==
'#'
)
continue
;
//--- Skip a symbol already collected from an earlier line, so the
//--- same symbol cannot be loaded twice and publish conflicting
//--- PC_MaxLots_<symbol> globals
bool
alreadyPresent =
false
;
for
(
int
p =
0
; p < outCount; p++)
        {
if
(outSymbols[p] == line)
           {
            alreadyPresent =
true
;
break
;
           }
        }
if
(alreadyPresent)
        {
Print
(
"SymbolRegistry: Duplicate symbol in universe file, skipping: "
, line);
continue
;
        }

      outSymbols[outCount] = line;
      outCount++;
     }
if
(!
FileIsEnding
(handle))
Print
(
"SymbolRegistry: Universe file exceeds MAX_SYMBOLS ("
, MAX_SYMBOLS,
"). Remaining entries were ignored."
);
FileClose
(handle);
return
(
true
);
