//+------------------------------------------------------------------+
//| Validates that a symbol is available and tradeable               |
//+------------------------------------------------------------------+
bool
CSymbolRegistry::ValidateSymbol(
const
string
symbol)
const
{
//--- Attempt to add to market watch if not already present
if
(!
SymbolSelect
(symbol,
true
))
     {
Print
(
"SymbolRegistry: SymbolSelect failed for "
, symbol,
". Error: "
,
GetLastError
());
return
(
false
);
     }
//--- Confirm the symbol is open for new trades. SYMBOL_TRADE_MODE_DISABLED
//--- blocks all trading; SYMBOL_TRADE_MODE_CLOSEONLY blocks new positions
//--- specifically, which this framework needs to open. Long-only and
//--- short-only modes are left to pass, since direction suitability
//--- depends on the strategy rather than on registry-level validation.
ENUM_SYMBOL_TRADE_MODE
tradeMode =
      (
ENUM_SYMBOL_TRADE_MODE
)
SymbolInfoInteger
(symbol,
SYMBOL_TRADE_MODE
);
if
(tradeMode ==
SYMBOL_TRADE_MODE_DISABLED
||
      tradeMode ==
SYMBOL_TRADE_MODE_CLOSEONLY
)
     {
Print
(
"SymbolRegistry: Symbol not open for new trades: "
, symbol);
return
(
false
);
     }
return
(
true
);
  }
