bool
CSymbolRegistry::LoadSymbolFromBroker(
const
string
symbol,
int
index)
  {
if
(index <
0
|| index >= MAX_SYMBOLS)
return
(
false
);
// FIX: local struct references ("SymbolMetadata &meta = m_Symbols[index];")
// are not valid MQL5 syntax outside a function parameter list.
// Write through m_Symbols[index] directly instead.
m_Symbols[index].
Symbol
= symbol;
   m_Symbols[index].ContractSize   =
SymbolInfoDouble
(symbol,
SYMBOL_TRADE_CONTRACT_SIZE
);
   m_Symbols[index].TickSize       =
SymbolInfoDouble
(symbol,
SYMBOL_TRADE_TICK_SIZE
);
   m_Symbols[index].TickValue      =
SymbolInfoDouble
(symbol,
SYMBOL_TRADE_TICK_VALUE
);
   m_Symbols[index].PointSize      =
SymbolInfoDouble
(symbol,
SYMBOL_POINT
);
   m_Symbols[index].
Digits
= (
int
)
SymbolInfoInteger
(symbol,
SYMBOL_DIGITS
);
   m_Symbols[index].VolumeMin      =
SymbolInfoDouble
(symbol,
SYMBOL_VOLUME_MIN
);
   m_Symbols[index].VolumeMax      =
SymbolInfoDouble
(symbol,
SYMBOL_VOLUME_MAX
);
   m_Symbols[index].VolumeStep     =
SymbolInfoDouble
(symbol,
SYMBOL_VOLUME_STEP
);
   m_Symbols[index].SpreadPoints   = (
double
)
SymbolInfoInteger
(symbol,
SYMBOL_SPREAD
);
   m_Symbols[index].ProfitCurrency =
SymbolInfoString
(symbol,
SYMBOL_CURRENCY_PROFIT
);
   m_Symbols[index].BaseCurrency   =
SymbolInfoString
(symbol,
SYMBOL_CURRENCY_BASE
);
//--- Sanity checks on critical fields
if
(m_Symbols[index].ContractSize <=
0.0
|| m_Symbols[index].TickSize <=
0.0
||
      m_Symbols[index].TickValue    <=
0.0
|| m_Symbols[index].VolumeStep <=
0.0
)
