if
(!m_Symbols[i].IsLoaded)
continue
;
string
sym = m_Symbols[i].
Symbol
;
double
freshTickValue =
SymbolInfoDouble
(sym,
SYMBOL_TRADE_TICK_VALUE
);
if
(freshTickValue <=
0.0
