//+------------------------------------------------------------------+
//| Normalize a raw lot value to the symbol's volume constraints     |
//+------------------------------------------------------------------+
double
CSymbolRegistry::GetNormalizedLots(
const
string
symbol,
double
rawLots)
const
{
int
idx = FindSymbolIndex(symbol);
if
(idx <
0
)
return
(
0.0
);
// FIX: replaced "const SymbolMetadata &meta = m_Symbols[idx];" with
// direct indexed access — local references are not valid MQL5 syntax.
if
(m_Symbols[idx].VolumeStep <=
0.0
)
return
(
0.0
);
double
normalized =
MathFloor
(rawLots / m_Symbols[idx].VolumeStep)
                       * m_Symbols[idx].VolumeStep;
//--- Round to the step's implied precision to clear floating-point
//--- artifacts (e.g. 0.07999999999 instead of 0.08) that MetaTrader
//--- can otherwise reject as an invalid volume
int
stepDigits = (
int
)
MathRound
(-
MathLog10
(m_Symbols[idx].VolumeStep));
   normalized =
NormalizeDouble
(normalized,
MathMax
(
0
, stepDigits));
//--- Below the minimum tradable size: the position is not achievable
//--- at this risk level. Returning 0 here, rather than rounding up to
//--- VolumeMin, keeps the function from silently exceeding the caller's
//--- risk-computed size.
if
(normalized < m_Symbols[idx].VolumeMin)
return
(
0.0
);

   normalized =
MathMin
(normalized, m_Symbols[idx].VolumeMax);
return
(normalized);
  }
