double
CSymbolRegistry::PipsToPoints(
const
string
symbol,
double
pips)
const
{
int
idx = FindSymbolIndex(symbol);
if
(idx <
0
)
return
(
0.0
);
// FIX: replaced local reference with direct indexed access.
//--- For 5-digit FX pairs, 1 pip = 10 points
//--- For 3-digit JPY pairs, 1 pip = 10 points (same logic)
//--- For metals and indices, pip convention varies — use tick size as base unit
double
pipInPoints =
0.0
;
if
(m_Symbols[idx].
Digits
==
5
|| m_Symbols[idx].
Digits
==
3
)
      pipInPoints =
10.0
;
else
if
(m_Symbols[idx].
Digits
==
2
|| m_Symbols[idx].
Digits
==
4
)
         pipInPoints =
1.0
;
else
pipInPoints = m_Symbols[idx].TickSize / m_Symbols[idx].PointSize;
return
(pips * pipInPoints);
