//| Convert a point distance to account currency value for N lots    |
//+------------------------------------------------------------------+
double
CSymbolRegistry::PointsToAccountCurrency(
const
string
symbol,
double
points,
double
lots)
const
{
int
idx = FindSymbolIndex(symbol);
if
(idx <
0
)
return
(
0.0
);
// FIX: replaced local reference with direct indexed access.
if
(m_Symbols[idx].TickSize <=
0.0
)
return
(
0.0
);
//--- Value of one point move = TickValue * (PointSize / TickSize)
double
pointValue = m_Symbols[idx].TickValue *
                       (m_Symbols[idx].PointSize / m_Symbols[idx].TickSize);
